import scala.Tuple2;

import java.util.*;

public class CacheHitRateCalculator {

    public static void main(String[] args) {
        // Initialize Spark context
        SparkConf conf = new SparkConf()
                .setAppName("Cache Hit Rate Calculator")
                .setMaster("local[*]");
        JavaSparkContext sc = new JavaSparkContext(conf);

        // Load onsite attributed data (query, timestamp)
        JavaRDD<String> onsiteData = sc.textFile("path/to/onsite_attributed_data.csv");

        // Load top frequent queries
        JavaRDD<String> topFrequentQueries = sc.textFile("path/to/top_frequent_queries.csv");

        // Broadcast top frequent queries for efficient lookup
        Set<String> topQueriesSet = new HashSet<>(topFrequentQueries.collect());
        final java.util.Map<String, Long> broadcastTopQueries = sc.broadcast(topQueriesSet).value();

        // Process onsite data to calculate cache hits and misses
        // Group by query to maintain order and count first occurrences
        JavaRDD<Tuple2<String, Iterable<String>>> groupedByQuery = onsiteData
                .map(line -> {
                    String[] parts = line.split(",");
                    String query = parts[0];
                    String timestamp = parts[1];
                    return new Tuple2<>(query, timestamp);
                })
                .groupByKey();

        // Calculate cache hits and misses
        long totalRequests = 0;
        long cacheMisses = 0;

        for (Tuple2<String, Iterable<String>> record : groupedByQuery.collect()) {
            String query = record._1;
            Iterator<String> timestamps = record._2.iterator();

            if (broadcastTopQueries.containsKey(query)) {
                // First occurrence is a cache miss
                if (timestamps.hasNext()) {
                    cacheMisses++;
                    totalRequests++;
                    timestamps.next(); // Consume first occurrence

                    // Subsequent occurrences within 12 hours are cache hits
                    while (timestamps.hasNext()) {
                        timestamps.next();
                        totalRequests++;
