                        // For simplicity, we count all subsequent as hits
                    }
                }
            } else {
                // Query not in top frequent queries, count all as misses
                Iterator<String> iter = record._2.iterator();
                while (iter.hasNext()) {
                    iter.next();
                    totalRequests++;
                    cacheMisses++;
                }
            }
        }

        // Calculate hit rate
        double hitRate = totalRequests > 0 ? (double) (totalRequests - cacheMisses) / totalRequests : 0.0;

        System.out.println("Total Requests: " + totalRequests);
        System.out.println("Cache Misses: " + cacheMisses);
        System.out.println("Cache Hits: " + (totalRequests - cacheMisses));
        System.out.println("Cache Hit Rate: " + (hitRate * 100) + "%");

        sc.stop();
    }
